  recipient: 'SP2J6ZY48GV1EZ5V2V5RB9MP66SW86PYKKQHX0A73',
  amount: 500000n,
  numSignatures: 2,
  publicKeys: [pubKey1, pubKey2, pubKey3],
  signerKeys: [privateKey1, privateKey2],
  network: 'mainnet',
});
```

