```ts
// Basic broadcast
import { broadcastTransaction, makeSTXTokenTransfer } from '@stacks/transactions';

const transaction = await makeSTXTokenTransfer({
  recipient: 'SP2J6ZY48GV1EZ5V2V5RB9MP66SW86PYKKQHX0A73',
  amount: 1000000n,
  senderKey: 'your-private-key-hex',
  network: 'testnet',
});

const result = await broadcastTransaction({ transaction, network: 'testnet' });
console.log(result);
```

```ts
// Broadcast with a custom client
import { broadcastTransaction } from '@stacks/transactions';

const result = await broadcastTransaction({
  transaction,
  client: {
    baseUrl: 'https://my-stacks-node.example.com',
  },
});

if (result.error) {
  console.error('Broadcast failed:', result.reason);
} else {
  console.log('Transaction ID:', result.txid);
}
```

