// Read the balance of a fungible token
import { fetchCallReadOnlyFunction, uintCV, standardPrincipalCV } from '@stacks/transactions';

const result = await fetchCallReadOnlyFunction({
  contractAddress: 'SP3FBR2AGK5H9QBDH3EEN6DF8EK8JY7RX8QJ5SVTE',
  contractName: 'sip-010-ft',
  functionName: 'get-balance',
  functionArgs: [standardPrincipalCV('SP2J6ZY48GV1EZ5V2V5RB9MP66SW86PYKKQHX0A73')],
  senderAddress: 'SP2J6ZY48GV1EZ5V2V5RB9MP66SW86PYKKQHX0A73',
  network: 'mainnet',
});

console.log(result); // (ok u1000000)
```

